"""FROZEN reference: the pre-merge ``create_checkout`` / ``warmup_approve_context``.

Generated mechanically from
``git show HEAD:services/protocol-payment/ideal/ideal_qr_extract.py`` before
stage 2 (batch 9) moved both into ``common/checkout_session.py``. The two bodies
were AST-identical in ideal / twint / blik once the provider token was
normalised away (parity: 109/109/102 lines and 22/22/22 lines; blik's 7-line gap
is one ``dump_http`` call collapsed onto a single line), so one copy represents
all three.

**Do not edit this file.** It is the "before" side of the differential test in
``tests/governance/test_stage2_replay_selfcheck.py``; editing it turns that test
into a comparison of the new code against itself.

The only transformation applied to the captured source is dependency injection:
every ambient name the body closed over is now an attribute of ``Seams``, which
the test fills from the extractor under test. No statement, literal or
expression was rewritten.

It deliberately does not import ``common``: that package only resolves after the
child-process ``sys.path`` setup, and pyright reports it as
``reportMissingImports`` from ``tests/``. The pre-existing test files carry a
frozen baseline row for exactly that finding; a new file is allowed no such row,
so the URL constants, the timeout and the three predicates are injected instead.
"""

from __future__ import annotations

import os
import re
from typing import Any

import requests


class Seams:
    """The per-extractor values and callables the pre-merge bodies closed over."""

    def __init__(
        self,
        *,
        normalize_country,
        currency_for_country,
        env_bool,
        env_int,
        log,
        dump_http,
        default_stripe_pk: str,
        coupon_fallback_flag: str,
        warmup_dump_flag: str,
        chatgpt_base: str,
        checkout_api: str,
        sentinel_ping: str,
        timeout: float,
        is_user_already_paid_error,
        checkout_response_has_promo,
        checkout_response_has_trial,
    ) -> None:
        self.normalize_country = normalize_country
        self.currency_for_country = currency_for_country
        self.env_bool = env_bool
        self.env_int = env_int
        self.log = log
        self.dump_http = dump_http
        self.default_stripe_pk = default_stripe_pk
        self.coupon_fallback_flag = coupon_fallback_flag
        self.warmup_dump_flag = warmup_dump_flag
        self.chatgpt_base = chatgpt_base
        self.checkout_api = checkout_api
        self.sentinel_ping = sentinel_ping
        self.timeout = timeout
        self.is_user_already_paid_error = is_user_already_paid_error
        self.checkout_response_has_promo = checkout_response_has_promo
        self.checkout_response_has_trial = checkout_response_has_trial


def create_checkout(chatgpt: requests.Session, country: str, *, seams: Seams) -> dict[str, str]:
    country = seams.normalize_country(country)
    promo_mode = os.environ.get("PP_PROMO_MODE", "campaign").strip().lower() or "campaign"
    promo_id = os.environ.get("PP_PROMO_ID", "plus-1-month-free").strip()
    body: dict[str, Any] = {
        "entry_point": os.environ.get("PP_ENTRY_POINT", "all_plans_pricing_modal"),
        "plan_name": "chatgptplusplan",
        "billing_details": {"country": country, "currency": seams.currency_for_country(country)},
        "checkout_ui_mode": "custom",
    }
    if promo_mode in ("trial", "free_trial"):
        trial_days = seams.env_int("PP_TRIAL_DAYS", 30)
        body["subscription_data"] = {"trial_period_days": trial_days}
    elif promo_mode in ("campaign", "query"):
        body["promo_campaign"] = {
            "promo_campaign_id": promo_id,
            "is_coupon_from_query_param": promo_mode == "query",
        }
    elif promo_mode == "coupon":
        body["coupon"] = promo_id
    elif promo_mode == "code":
        body["promotion_code"] = promo_id
    elif promo_mode != "off":
        seams.log(f"未知 PP_PROMO_MODE={promo_mode!r}，已忽略", "[WARN] ")
    seams.log(f"Checkout promo: mode={promo_mode}, id={promo_id}")

    headers = {
        "Referer": seams.chatgpt_base + "/",
        "x-openai-target-path": "/backend-api/payments/checkout",
        "x-openai-target-route": "/backend-api/payments/checkout",
    }
    resp = chatgpt.post(
        seams.checkout_api,
        json=body,
        headers=headers,
        timeout=seams.timeout,
    )
    seams.dump_http(
        resp,
        "checkout",
        body,
        "POST",
        seams.checkout_api,
        force=resp.status_code >= 400,
    )
    if resp.status_code >= 400:
        if seams.is_user_already_paid_error(resp.text):
            raise RuntimeError("用户已支付: User is already paid")
        raise RuntimeError(f"checkout 创建失败 HTTP {resp.status_code}: {resp.text[:500]}")

    data = resp.json() or {}
    if (
        promo_mode == "coupon"
        and promo_id == "plus-1-month-free"
        and not seams.checkout_response_has_promo(data)
        and seams.env_bool(seams.coupon_fallback_flag, True)
    ):
        seams.log("coupon 响应未显示优惠，按 promo_campaign 字符串重试", "[PROMO] ")
        fallback_body = dict(body)
        fallback_body.pop("coupon", None)
        fallback_body["promo_campaign"] = promo_id
        resp = chatgpt.post(
            seams.checkout_api,
            json=fallback_body,
            headers=headers,
            timeout=seams.timeout,
        )
        seams.dump_http(
            resp,
            "checkout_promo_campaign",
            fallback_body,
            "POST",
            seams.checkout_api,
            force=True,
        )
        if resp.status_code >= 400:
            if seams.is_user_already_paid_error(resp.text):
                raise RuntimeError("用户已支付: User is already paid")
            raise RuntimeError(f"checkout promo_campaign 重试失败 HTTP {resp.status_code}: {resp.text[:500]}")
        data = resp.json() or {}
        seams.log(f"promo_campaign 重试后 promo={seams.checkout_response_has_promo(data)}", "[PROMO] ")

    cs_id = data.get("checkout_session_id") or data.get("session_id") or data.get("id")
    if not cs_id or not str(cs_id).startswith("cs_"):
        raise RuntimeError(f"checkout 响应缺少 cs_id: {str(data)[:500]}")

    raw_pk = (
        data.get("stripe_publishable_key")
        or data.get("publishable_key")
        or data.get("publishableKey")
        or data.get("stripePublishableKey")
        or data.get("key")
        or ""
    )
    match = re.search(r"pk_live_[A-Za-z0-9]+", str(raw_pk))
    stripe_pk = match.group(0) if match else seams.default_stripe_pk
    processor_entity = str(data.get("processor_entity") or data.get("processorEntity") or "")
    seams.log(
        f"Checkout 创建成功: {cs_id} / {country} / {seams.currency_for_country(country)} / "
        f"mode={promo_mode} / promo={seams.checkout_response_has_promo(data)} / "
        f"trial={seams.checkout_response_has_trial(data)}"
    )
    return {
        "cs_id": str(cs_id),
        "processor_entity": processor_entity,
        "stripe_pk": stripe_pk,
        "billing_country": country,
        "currency": seams.currency_for_country(country),
    }


def warmup_approve_context(chatgpt: requests.Session, checkout_page_url: str, *, seams: Seams) -> None:
    try:
        resp = chatgpt.post(
            seams.sentinel_ping,
            json={},
            headers={
                "Referer": seams.chatgpt_base + "/",
                "x-openai-target-path": "/backend-api/sentinel/ping",
                "x-openai-target-route": "/backend-api/sentinel/ping",
            },
            timeout=seams.timeout,
        )
        seams.dump_http(
            resp,
            "sentinel_ping",
            {},
            "POST",
            seams.sentinel_ping,
            force=seams.env_bool(seams.warmup_dump_flag, False),
        )
    except Exception as exc:
        seams.log(f"approve sentinel 请求异常: {exc}", "[WARN] ")
